#ifndef MAELYS_GIT_CLI_SUPPORT_H
#define MAELYS_GIT_CLI_SUPPORT_H

/* Internal helpers shared by the product command handlers. */

#include "maelys_git_cli.h"
#include "maelys_git_schemas.h" /* generated by maelys-cli-embed from schemas/ */

#include <stddef.h>

#define MAELYS_GIT_CLI_DEFAULT_GIT "/usr/bin/git"
#define MAELYS_GIT_CLI_PATH_MAX 4096u

/* The snapshot of grants a policy set reads, for every command that opens a
 * manifest. */
#define MAELYS_GIT_CLI_GRANTS_OPTION \
    {MAELYS_CLI_PATH("grants", "FILE", \
     "Snapshot of Gitolite grants (maelys-git-grants/1) the audited Gitolite program reads.")}

/* Summary shared by every --git option. */
#define MAELYS_GIT_CLI_GIT_OPTION \
    {MAELYS_CLI_ABSOLUTE_PATH("git", "FILE", "Absolute Git executable path."), \
     .default_text = MAELYS_GIT_CLI_DEFAULT_GIT}

/* Object identifier operand: 40 (SHA-1) or 64 (SHA-256) lowercase hex digits. */
#define MAELYS_GIT_CLI_OID_OPERAND(name_, summary_) \
    {MAELYS_CLI_OPERAND_KIND(name_, summary_, MAELYS_CLI_VALUE_HEX), \
     .hex_digits = 40u, .hex_digits_alternative = 64u}
#define MAELYS_GIT_CLI_ABSOLUTE_OPERAND(name_, summary_) \
    {MAELYS_CLI_OPERAND_KIND(name_, summary_, MAELYS_CLI_VALUE_ABSOLUTE_PATH)}

/* Value of --git; the catalog default applies when absent. */
const char *maelys_git_cli_git(const maelys_cli_context_t *context);

/* Failure of a protocol-stream command, on stderr only: the line
 * `PROGRAM OPERATION error [result]: message`, or the JSON failure envelope
 * of maelys_git_cli_fail_result() when MAELYS_CLI_FORMAT=json. stdout is
 * never touched; returns MAELYS_CLI_EXIT_FAILURE. */
int maelys_git_cli_stream_error(
    maelys_cli_context_t *context,
    const char *operation,
    maelys_git_result_t result,
    const maelys_git_error_t *error);

/* Opens a policy manifest, with the snapshot of grants GRANTS_PATH when it
 * is not NULL; on failure the envelope is emitted and the exit code
 * returned, otherwise 0. */
int maelys_git_cli_open_policy(
    maelys_cli_context_t *context,
    const char *manifest_path,
    const char *grants_path,
    maelys_git_policy_t **out_policy);

/* Resolves REPOSITORY below ROOT; same contract as maelys_git_cli_open_policy. */
int maelys_git_cli_resolve_repository(
    maelys_cli_context_t *context,
    const char *repository_root,
    const char *repository_name,
    char *out_path,
    size_t out_capacity);

#endif
